css:
.glass-nav {
            background: rgba(255, 255, 255, 0.1);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border-bottom: 1px solid rgba(255, 255, 255, 0.2);
            z-index: 2147483647 !important;
            isolation: isolate !important;
            pointer-events: auto !important;
        }
.glass-nav * {
            position: relative;
            z-index: 2147483647 !important;
            pointer-events: auto !important;
        }
.hamburger-btn {
            display: none;
            background: rgba(255,255,255,0.2);
            border: none;
            color: white;
            width: 44px;
            height: 44px;
            border-radius: 8px;
            cursor: pointer;
            font-size: 20px;
            z-index: 99999;
        }
.mobile-menu {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(135deg, rgba(102,126,234,0.98) 0%, rgba(118,75,162,0.98) 100%);
            z-index: 99998;
            display: none;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            padding: 20px;
        }
.mobile-menu.show {
            display: flex;
        }
.mobile-menu-item {
            color: white;
            font-size: 18px;
            font-weight: 600;
            padding: 15px 30px;
            text-decoration: none;
            text-align: center;
            width: 100%;
            max-width: 300px;
            border-bottom: 1px solid rgba(255,255,255,0.2);
            transition: all 0.3s;
        }
.close-menu-btn {
            position: absolute;
            top: 20px;
            right: 20px;
            background: rgba(255,255,255,0.2);
            border: none;
            color: white;
            width: 44px;
            height: 44px;
            border-radius: 8px;
            cursor: pointer;
            font-size: 20px;
        }
@media (max-width: 768px) {
            .nav-links {
                display: none !important;
            }

            .hamburger-btn {
                display: block !important;
            }
